import{_ as t,l as n,o as e,c as l,v as r,p as s,x as i,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"基数估计误差传播","description":"","frontmatter":{"title":"基数估计误差传播","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cardinality-error-propagation.md","filePath":"cs/cardinality-error-propagation.md","lastUpdated":1789023840000}'),h={name:"cs/cardinality-error-propagation.md"};function c(m,a,A,_,B,D){const o=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="基数估计误差传播" tabindex="-1">基数估计误差传播 <a class="header-anchor" href="#基数估计误差传播" aria-label="Permalink to &quot;基数估计误差传播&quot;">​</a></h1><div class="epigraph"><p>选择率相乘把相对误差指数放大；中间结果估错一个数量级，动态规划就在错误的地图上找最短路。</p><footer>—— 据 Ioannidis and Christodoulakis；Lohman；Selinger 代价模型对照；Ramakrishnan and Gehrke</footer></div><p><a href="/cs/join-order-space">上一课</a>画出连接树空间。本课不枚举 Catalan 数。缺口是树上的数字：主干直方图给出单谓词选择率；多谓词、多连接之后，独立假设把误差连乘。优化器单元必须承认：<strong>DP 精确不等于计划好</strong>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单列等值：选择率 \\(1/\\mathrm{NDV}\\) 或高频值。两列相关（城市与邮编）独立假设会把联合选择率估得过小或过大。连接：\\(|R \\bowtie S| \\approx |R||S|/\\max(\\mathrm{NDV}(R.k),\\mathrm{NDV}(S.k))\\) 一类公式，再错一层。沿左深树 \\(n{-}1\\) 次相乘，相对误差可指数增长（Ioannidis 等指出优化对误差极敏感）。</p><p>缺口不是再画等宽桶，而是传播：哪个节点的误差最伤（靠近根的大中间结果），以及「低估」通常比「高估」更伤——低估会选 NLJ 打大表，内存爆；高估常选更保守的哈希/排序，慢但不至于灾难。</p><p><span class="marginnote">Ioannidis and Christodoulakis 讨论优化对估计误差的敏感性。Lohman 总结代价优化的工程。本课不发明新公式冒充已发表结果。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>诊断：计划中的估计行数 vs 实际行数（explain analyze）。误差比沿路径看是放大还是抵消。缓解：多列统计、函数依赖（邮编→城市）、采样、直方图桶加密。本课点名方向，采样草图下一课。</p><p>逻辑改写先减树高（下推），减少相乘次数，是误差控制的一部分，不只是「更快」。</p>',10)),(e(),s(E,null,{default:i(()=>[p(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEL%5B%22%E5%8D%95%E8%B0%93%E8%AF%8D%E9%80%89%E6%8B%A9%E7%8E%87%22%5D%20--%3E%20IND%5B%22%E7%8B%AC%E7%AB%8B%E5%81%87%E8%AE%BE%E8%BF%9E%E4%B9%98%22%5D%0A%20%20IND%20--%3E%20MID%5B%22%E4%B8%AD%E9%97%B4%E5%9F%BA%E6%95%B0%22%5D%0A%20%20MID%20--%3E%20DP%5B%22DP%20%E9%80%89%E7%AE%97%E5%AD%90%E4%B8%8E%E9%A1%BA%E5%BA%8F%22%5D%0A%20%20MID%20--%3E%20ERR%5B%22%E7%9B%B8%E5%AF%B9%E8%AF%AF%E5%B7%AE%E6%94%BE%E5%A4%A7%22%5D%0A%20%20ERR%20--%3E%20BAD%5B%22%E9%94%99%E9%80%89%20NLJ%20%2F%20%E9%94%99%20build%20%E4%BE%A7%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有趣序不救错误基数：归并看起来便宜是因为估小了无序输入。计划缓存会把第一次的错误数字锁死。自适应查询处理（后课）在执行中发现误差再换计划，是承认静态估计不够。</p><p>NULL 与包：选择率要计入 NULL 比例，否则等值谓词估错。三值课已有，估计模块必须读目录里的 NULL 统计。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把学习基数估计当默认——更后课学习型优化器。也不校准 I/O 常数。采样与草图下一课给执行期或 ANALYZE 期的另一种输入。</p><p>后课默认：看计划先看估计/实际比，再谈有没有索引。连乘独立假设是默认谎言，相关列要显式统计。</p><p>DP 的最优性相对模型；模型的输入是带噪声的基数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>选择率相乘放大误差；低估常导致灾难性算子选择。</li><li>多列统计与下推减少相乘层数。</li><li>采样与草图下一课：用数据样本修正目录谎言。</li><li>出处：Ioannidis and Christodoulakis；Lohman；Selinger；Ramakrishnan and Gehrke。</li></ul>',9))])}const k=t(h,[["render",c]]);export{f as __pageData,k as default};
